CREATE TABLE private_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),uploaded_by uuid NOT NULL REFERENCES users(id),object_key text UNIQUE NOT NULL,mime text NOT NULL CHECK(mime IN ('application/pdf','image/jpeg','image/png')),size_bytes integer NOT NULL CHECK(size_bytes>0 AND size_bytes<=10485760),sha256 text NOT NULL,state text NOT NULL DEFAULT 'quarantined' CHECK(state IN ('quarantined','clean','rejected')),scan_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id));
ALTER TABLE private_files ENABLE ROW LEVEL SECURITY; ALTER TABLE private_files FORCE ROW LEVEL SECURITY;
CREATE POLICY file_owner ON private_files USING(organization_id=current_org() AND EXISTS(SELECT FROM memberships m WHERE m.organization_id=private_files.organization_id AND m.user_id=current_actor() AND m.role='Owner' AND m.revoked_at IS NULL)) WITH CHECK(organization_id=current_org() AND EXISTS(SELECT FROM memberships m WHERE m.organization_id=private_files.organization_id AND m.user_id=current_actor() AND m.role='Owner' AND m.revoked_at IS NULL));
GRANT SELECT,INSERT,UPDATE ON private_files TO kost_app;
CREATE TABLE idempotency_requests(organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid NOT NULL REFERENCES users(id),command text NOT NULL,key text NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,actor_id,command,key));
ALTER TABLE idempotency_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE idempotency_requests FORCE ROW LEVEL SECURITY;
CREATE POLICY idempotency_actor ON idempotency_requests USING(organization_id=current_org() AND actor_id=current_actor() AND EXISTS(SELECT FROM memberships m WHERE m.organization_id=idempotency_requests.organization_id AND m.revoked_at IS NULL)) WITH CHECK(organization_id=current_org() AND actor_id=current_actor() AND EXISTS(SELECT FROM memberships m WHERE m.organization_id=idempotency_requests.organization_id AND m.revoked_at IS NULL));
GRANT SELECT,INSERT ON idempotency_requests TO kost_app;
